You can use the following code to get the ASCII art of an image:
```
import os, subprocess

def ascii_art(img):
    img = img.convert('1') # Convert to black and white
    w, h = img.size
    rows = []
    for y in xrange(h):
        row = ''
        for x in xrange(w):
            row += '*' if img.getpixel((x, y)) else''
        rows.append(row)
    return os.linesep.join(rows)

def main():
    img = Image.open('image.jpg')
    print ascii_art(img)

if __name__ == '__main__':
    main()
```
