# Sudoku solver
# https://www.hackerrank.com/challenges/sudoku/problem

import itertools

def find_empty_cells(board):
    for i in range(9):
        for j in range(9):
            if board[i][j] == 0:
                return (i, j)
    return None

def valid(board, num, pos):
    row = pos[0]
    col = pos[1]

    for i in range(9):
        if board[row][i] == num and i!= col:
            return False
        if board[i][col] == num and i!= row:
            return False

    row_start = (row // 3) * 3
    col_start = (col // 3) * 3

    for i in range(row_start, row_start + 3):
        for j in range(col_start, col_start + 3):
            if board[i][j] == num and (i, j)!= pos:
                return False

    return True

def solve(board):
    find = find_empty_cells(board)

    if not find:
        return True
    else:
        row, col = find

    for i in range(1, 10):
        if valid(board, i, (row, col)):
            board[row][col] = i

            if solve(board):
                return True

            board[row][col] = 0

    return False

