#include <iostream>
using namespace std;

int fib(int n)
{
    int a = 0;
    int b = 1;
    int c = 0;
    for (int i = 2; i <= n; i++)
    {
        c = a + b;
        a = b;
        b = c;
    }
    return c;
}

int main()
{
    int n;
    cin >> n;
    cout << fib(n) << endl;
    return 0;
}

class Stack:
    def __init__(self):
        self.items = []

    def is_empty(self):
        return self.items == []

    def push(self, data):
        self.items.append(data)

    def pop(self):
        return self.items.pop()

    def peek(self):
        return self.items[-1]

    def size(self):
        return len(self.items)


 class Queue:
    def __init__(self):
        self.instack = Stack()
        self.outstack = Stack()

    def enqueue(self, data):
        self.instack.push(data)

    def dequeue(self):
        if self.outstack.is_empty():
            if not self.instack.is_empty():
                while not self.instack.is_empty():
                    self.outstack.push(self.instack.pop())

        return self.outstack.pop()

    def peek(self):
        if self.outstack.is_empty():
            if not self.instack.is_empty():
                while not self.instack.is_empty():
                    self.outstack.push(self.instack.pop())

        return self.outstack.peek()

    def size(self):
        return self.instack.size() + self.outstack.size()

    def is_empty(self):
        return self.instack.is_empty() and self.outstack.is_empty()

 q = Queue()
 q.enqueue(1)
 q.enqueue(2)
 q.enqueue(3)
 print(q.dequeue())
 print(q.dequeue())
 print(q.dequeue())
 print(q.is_empty())
